function evEnglishFoodName(name){
  var n=evAscii(String(name||''));
  if(n.indexOf('portakal')>=0) return 'orange';
  if(n.indexOf('elma')>=0) return 'apple';
  if(n.indexOf('muz')>=0) return 'banana';
  if(n.indexOf('zum')>=0 || n.indexOf('uzum')>=0) return 'grapes';
  if(n.indexOf('sut')>=0) return 'milk';
  if(n.indexOf('bal')>=0) return 'honey';
  if(n.indexOf('havuc')>=0 || n.indexOf('havu')>=0) return 'carrot';
  if(n.indexOf('brokoli')>=0) return 'broccoli';
  if(n.indexOf('mersini')>=0) return 'blueberries';
  if(n.indexOf('limon')>=0) return 'lemon';
  if(n.indexOf('kestane')>=0) return 'chestnut';
  if(n.indexOf('hurma')>=0) return 'date';
  if(n.indexOf('zeytin')>=0) return 'olive';
  if(n.indexOf('kivi')>=0) return 'kiwi';
  if(n.indexOf('kiraz')>=0) return 'cherry';
  return 'food';
}
