  if(n.indexOf('zum')>=0 || n.indexOf('?z')>=0) return 'Trauben';
  if(n.indexOf('sut')>=0 || n.indexOf('s?t')>=0) return 'Milch';
  if(n.indexOf('bal')>=0) return 'Honig';
  if(n.indexOf('havuc')>=0 || n.indexOf('havu')>=0) return 'Karotte';
  if(n.indexOf('brokoli')>=0) return 'Brokkoli';
  if(n.indexOf('mersini')>=0) return 'Blaubeeren';
  if(n.indexOf('limon')>=0) return 'Zitrone';
  if(n.indexOf('kestane')>=0) return 'Kastanie';
  if(n.indexOf('hurma')>=0) return 'Dattel';
  if(n.indexOf('zeytin')>=0) return 'Olive';
