function _snMuzik(){
  var a=document.getElementById('sn-audio');
  if(a){ a.currentTime=0; a.play(); }
}
function _snStopMuzik(){
  var a=document.getElementById('sn-audio');
  if(a){ a.pause(); a.currentTime=0; }
}
function _snStopMuzik(){
  var a=document.getElementById('sn-audio');
  if(a){a.pause();a.currentTime=0;}
}

function _snPlayNote(sceneIdx){
  try{
    var A=getAC(), t=A.currentTime;
    var scale=[523,587,659,698,784,880,988,1047];
    var idx=((sceneIdx||0)%8+8)%8;
    var chord=[scale[idx], scale[(idx+2)%8], scale[(idx+4)%8]];
    chord.forEach(function(freq,i){
      var o=A.createOscillator(), g=A.createGain();
      o.type='sine';
      o.frequency.value=freq;
      g.gain.setValueAtTime(0,t+i*0.06);
      g.gain.linearRampToValueAtTime(0.12,t+i*0.06+0.04);
      g.gain.exponentialRampToValueAtTime(0.001,t+i*0.06+0.5);
      o.connect(g); g.connect(A.destination);
      o.start(t+i*0.06); o.stop(t+i*0.06+0.55);
    });
  }catch(e){}
}function initOki(){
  loadSavedChar();
  var imgs=_CHARS[_selectedChar]||_CHARS.erkek;
  var mi=document.getElementById('char-main-img');
  var gi=document.getElementById('char-game-img');
  if(mi) mi.src=imgs.idle;
  if(gi) gi.src=imgs.idle;
  updateGrowthUI();
  setCharState('idle');
}
var _shopTalkTimer = null;
if(!CanvasRenderingContext2D.prototype.roundRect){
  CanvasRenderingContext2D.prototype.roundRect=function(x,y,w,h,r){
    r=Math.min(Math.abs(r||0),Math.abs(w)/2,Math.abs(h)/2);
    this.beginPath();
    this.moveTo(x+r,y); this.lineTo(x+w-r,y); this.arcTo(x+w,y,x+w,y+r,r);
    this.lineTo(x+w,y+h-r); this.arcTo(x+w,y+h,x+w-r,y+h,r);
    this.lineTo(x+r,y+h); this.arcTo(x,y+h,x,y+h-r,r);
    this.lineTo(x,y+r); this.arcTo(x,y,x+r,y,r);
    this.closePath(); return this;
  };
}

