    var roomCol=window._kumandaCol||'rgba(80,80,200,.12)';
    var rcg=ctx.createRadialGradient(W*.5,H*.5,H*.05,W*.5,H*.5,H*.7);
    rcg.addColorStop(0,roomCol); rcg.addColorStop(1,'transparent');
    ctx.fillStyle=rcg; ctx.fillRect(0,0,W,H);
    // Grid lines
    ctx.strokeStyle='rgba(60,60,180,.06)'; ctx.lineWidth=1;
    for(var gx=0;gx<W;gx+=W*.1){ctx.beginPath();ctx.moveTo(gx,0);ctx.lineTo(gx,H);ctx.stroke();}
    for(var gy=0;gy<H;gy+=H*.1){ctx.beginPath();ctx.moveTo(0,gy);ctx.lineTo(W,gy);ctx.stroke();}
