    var fl=window._kumandaFlash||0;
    if(fl>0){
      var fc=window._kumandaFlashCol||'rgba(255,100,100,.3)';
      ctx.fillStyle=fc; ctx.fillRect(0,0,W,H);
      window._kumandaFlash=fl-1;
    }
    // TV/Screen on wall
    ctx.fillStyle='rgba(5,5,30,.9)'; ctx.beginPath(); ctx.roundRect(W*.15,H*.05,W*.7,H*.38,6); ctx.fill();
    ctx.strokeStyle='rgba(80,80,200,.4)'; ctx.lineWidth=3; ctx.beginPath(); ctx.roundRect(W*.15,H*.05,W*.7,H*.38,6); ctx.stroke();
    // Screen content - changes with color
    var sc=window._kumandaCol||'rgba(20,20,80,.5)';
    var scg2=ctx.createLinearGradient(W*.16,H*.06,W*.16,H*.42);
    scg2.addColorStop(0,sc); scg2.addColorStop(1,'rgba(5,5,20,.8)');
