// ── STREAK ──
function getTodayStr(){ return new Date().toDateString(); }
function getStreak(){
  var last=localStorage.getItem('dei_last');
  var sc=parseInt(localStorage.getItem('dei_streak')||'0');
  if(!last) return 0;
  var yest=new Date(); yest.setDate(yest.getDate()-1);
  return (last===getTodayStr()||last===yest.toDateString())?sc:0;
}
function updateStreak(){
  var today=getTodayStr(),last=localStorage.getItem('dei_last');
  if(last===today) return;
  var sc=parseInt(localStorage.getItem('dei_streak')||'0');
  var yest=new Date(); yest.setDate(yest.getDate()-1);
  sc=(!last||last===yest.toDateString())?sc+1:1;
  localStorage.setItem('dei_streak',sc); localStorage.setItem('dei_last',today);
}

