function evRoomDisplayName(room){
  if(!(evValuesOn&&evValuesOn&&evValuesOn()&&evValuesLang)) return room.name;
  if(evValuesLang()==='en'){
    var en={ibadet:'Reflection Room',sinema:'Cinema',ders:'Learning Room',oyuncak:'Play Room',cevre:'Nature Room',caliskan:'Goal Room',sanat:'Art Studio',mutfak:'Kitchen',aile:'Family Room',ada:'Island',sifa:'Wellness Room',ilkbahar:'Spring Room',odulodasi:'Reward Room',nefes:'Breathing Room',para:'Money Room',arapca:'Letters Room',gizli:'Secret Room',english:'English Room',deutsch:'German Room',okyanus:'Ocean Room',atlas:'World Explorer',muzik:'Music Room',boyama:'Color Room',kumanda:'Game Room',puzzle:'Puzzle Room',lazer:'Laser Room',bilgisayar:'Computer Room',hayvanat:'Animal World',refleks:'Reflex Room'};
    return en[room.id]||room.name;
  }
  if(evValuesLang()==='de'){
    var de={ders:'Lernen',atlas:'Welt-Entdecker',puzzle:'Puzzle',nefes:'Atem-Raum',sanat:'Kreativraum',boyama:'Malraum',refleks:'Reflex-Raum',hayvanat:'Tierwelt',kelime:'Woerter',gorev:'Aufgaben',odak:'Fokus-Raum',lazer:'Laser-Raum',sinema:'Kino',okul:'Schulraum',dukkan:'Laden',market:'Laden',muzik:'Musik',oyuncak:'Spiel',ada:'Insel',caliskan:'Lernziel',cevre:'Natur',aile:'Familie'};
    return de[room.id]||room.name;
  }
  if(evValuesLang()==='fr'){
    var fr={ibadet:'Salle calme',sinema:'Cin\u00e9ma',ders:'Salle d\u2019apprentissage',oyuncak:'Salle de jeux',cevre:'Prot\u00e9ger la plan\u00e8te',caliskan:'Salle de l\u2019effort',sanat:'Atelier d\u2019art',mutfak:'Laboratoire cuisine',aile:'Salle de la famille',ada:'\u00cele tranquille',sifa:'Salle du bien-\u00eatre',ilkbahar:'Jardin du printemps',odulodasi:'Salle des r\u00e9compenses',nefes:'Salle de respiration',para:'Salle du partage',arapca:'Lettres du monde',gizli:'Salle myst\u00e8re',english:'Salle d\u2019anglais',deutsch:'Salle d\u2019allemand',okyanus:'Salle oc\u00e9an',atlas:'Explorateur du monde',muzik:'Salle de musique',boyama:'Salle des couleurs',kumanda:'Salle de jeux vid\u00e9o',puzzle:'Salle puzzle',lazer:'Salle laser',bilgisayar:'Salle informatique',hayvanat:'Monde animal',refleks:'Salle r\u00e9flexe'};
    return fr[room.id]||room.name;
  }
  return room.name;
}

function evSafeVisibleIcon(value,fallback){
  var s=String(value||'');
  return /[\u00C2-\u00C5\u00E2]/.test(s)?(fallback||''):s;
}
function evRoomDisplayIcon(room){
  var icons={ibadet:'\uD83E\uDDD8',sinema:'\uD83C\uDFAC',ders:'\uD83D\uDCDA',oyuncak:'\uD83E\uDDF8',cevre:'\uD83C\uDF31',caliskan:'\uD83D\uDCAA',sanat:'\uD83C\uDFA8',mutfak:'\uD83C\uDF73',aile:'\uD83D\uDC6A',ada:'\uD83C\uDFDD\uFE0F',sifa:'\uD83C\uDF3F',ilkbahar:'\uD83C\uDF38',odulodasi:'\uD83C\uDFC6',nefes:'\uD83C\uDF2C\uFE0F',para:'\uD83D\uDCB0',arapca:'\u270D\uFE0F',gizli:'\uD83D\uDD2E',english:'\uD83C\uDDEC\uD83C\uDDE7',deutsch:'\uD83C\uDDE9\uD83C\uDDEA',okyanus:'\uD83C\uDF0A',atlas:'\uD83C\uDF0C',muzik:'\uD83C\uDFB5',boyama:'\uD83D\uDD8C\uFE0F',kumanda:'\uD83C\uDFAE',puzzle:'\uD83E\uDDE9',lazer:'\u26A1',bilgisayar:'\uD83D\uDCBB',hayvanat:'\uD83E\uDD81',refleks:'\u26A1'};
  return icons[room&&room.id]||'\u2728';
}
function buildGrid(){
  var grid=document.getElementById('rgrid');
  grid.innerHTML='';
  updateStreak();
  var streak=getStreak();
  var sm=document.getElementById('streak-msg');
  if(streak>=5){
    var sr=ROOMS.find(function(r){return r.id==='gizli';}); if(sr) sr.unlock=0;
    sm.textContent=evText('Gizli Oda Acik! 5 gun tamamlandi!'); sm.style.display='block';
  } else if(streak>0){
    sm.textContent=(evValuesOn()&&evValuesLang()==='fr')?(streak+'/5 jour - Salle mystere dans '+(5-streak)+' jours !'):(evValuesOn()&&evValuesLang()==='ar')?(streak+'/5 يوم - الغرفة الغامضة بعد '+(5-streak)+' أيام!'):(streak+'/5 '+evText('gun')+' - '+evText('Gizli Oda icin')+' '+(5-streak)+' '+evText('gun kaldi')+'!'); sm.style.display='block';
  } else { sm.style.display='none'; }
  ROOMS.forEach(function(room){
    var _vo=!!(window.evValuesOn&&evValuesOn())||localStorage.getItem('eduverse_values_mode')==='1';
    var locked=room.id==='sinema'?false:(_vo?false:(totalScore<room.unlock));
    var best=roomBests[room.id]||0;
    var btn=document.createElement('button');
    btn.className='rb'+(locked&&room.id!=='sinema'?' locked':'');
    var arGrid = evArabicActive&&evArabicActive();
    var bestLabel = arGrid ? '\u0627\u0644\u0623\u0641\u0636\u0644' : evText('En iyi');
    var watchLabel = arGrid ? '\u0645\u0634\u0627\u0647\u062F\u0629' : evText('Izle');
    btn.innerHTML='<div class="rb-ico">'+evRoomDisplayIcon(room)+'</div><div class="rb-name">'+evRoomDisplayName(room)+'</div><div class="rb-info">'+(locked&&room.id!=='sinema'?'\uD83D\uDD12 '+room.unlock+'\u2B50':best&&room.id!=='sinema'?best+'\u2B50 '+bestLabel:'\u25B6 '+watchLabel+'!')+'</div>';
    if(!locked||room.id==='sinema') btn.onclick=function(){enterRoom(room);};
    grid.appendChild(btn);
  });
}

function enterRoom(room){
  if(room.special==='sinema'){openSinema();return;}
  if(room.special==='hikaye'){openHikaye();return;}
  if(room.special==='refleks'){
    // Refleks odasında soru balonu istemiyoruz
    _soruState.answerBalloonPending=false;
    _soruState.active=false;
    openRefleks();return;
  }
  if(room.special==='puzzle'||room.special==='boyama'){
    // Puzzle/boyama için de soru sor
    showRoomSoru(room, function(){
      _soruState.answerBalloonPending=false; // Bu odalarda balon yok
      if(room.special==='puzzle'){openPuzzle();return;}
      if(room.special==='boyama'){openBoyama();return;}
    });
    return;
  }
  showRoomSoru(room, function(){
    _showRoomHook(room, function(){ _doEnterRoom(room); });
  });
}

function _showRoomHook(room, cb){
  var ov=document.getElementById('room-hook-ov');
  var card=document.getElementById('room-hook-card');
  var ico=document.getElementById('room-hook-ico');
  var name=document.getElementById('room-hook-name');
  var sub=document.getElementById('room-hook-sub');
  var bar=document.getElementById('room-hook-bar');
  if(!ov||!card){cb();return;}
  if(ico){ ico.textContent=''; ico.style.display='none'; }
  if(name) name.textContent=(typeof evRoomDisplayName==='function'?evRoomDisplayName(room):evText(room.name));
  if(sub) sub.textContent=(evJarLang&&evJarLang()==='de')?'Bereit?':((evJarLang&&evJarLang()==='en')?'Ready?':'Hazir misin?');
  bar.style.transition='none';
  bar.style.width='0%';
  ov.style.display='flex';
  ov.style.pointerEvents='auto';
  // Bg fade in
  setTimeout(function(){ ov.style.background='rgba(8,12,24,.18)'; },10);
  // Card pop in
  setTimeout(function(){
    card.style.transform='scale(1)';
    card.style.opacity='1';
    // Bar dolu
    setTimeout(function(){ bar.style.transition='width 2s linear'; bar.style.width='100%'; },50);
  },80);
  // Kapan
  setTimeout(function(){
    card.style.transform='scale(1.1)';
    card.style.opacity='0';
    ov.style.background='rgba(0,0,0,0)';
    setTimeout(function(){
      ov.style.display='none';
      ov.style.pointerEvents='none';
      card.style.transform='scale(0)';
      card.style.opacity='0';
      cb();
    },350);
  },2400);
}
function _doEnterRoom(room){
  // Müzik player her odada görünür
  setTimeout(function(){
    var m=document.getElementById('ada-muzik');
    if(m) m.style.display='flex';
  },400);
  // puzzle/boyama enterRoom başında yakalandı
  if(room.special==='hazine'){
    var hzd=JSON.parse(localStorage.getItem(_hzKey())||'{}');
    if(hzd.done){ showHazineDone(); return; }
    currentRoom=room; roomScore=0; objs=[]; parts=[]; lastSpawn=0;
    initCanvas();
    document.getElementById('gs').style.display='block';
    document.getElementById('hm').style.display='none';
    document.getElementById('gri').textContent=evRoomDisplayIcon(room);
    document.getElementById('grn').textContent=evRoomDisplayName(room);
    document.getElementById('gsn').textContent='0';
    document.getElementById('gp').style.width='0%';
    W=window.innerWidth; H=window.innerHeight;
    gameActive=true;
    return;
  }
  currentRoom=room; roomScore=0; objs=[]; parts=[]; lastSpawn=0;
  initCanvas();
  document.getElementById('gs').style.display='block';
  document.getElementById('hm').style.display='none';
  document.getElementById('gri').textContent=evRoomDisplayIcon(room);
  document.getElementById('grn').textContent=evRoomDisplayName(room);
  document.getElementById('gsn').textContent='0';
  document.getElementById('gp').style.width='0%';
  W=window.innerWidth; H=window.innerHeight;
  // Ders mesajı kaldırıldı
  gameActive=true;
  if(typeof okiEnterRoom==='function') okiEnterRoom(room.id);
  setTimeout(function(){
    if(room.id==='dua'&&_selectedChar==='kiz') versePray&&versePray();
    else charSurprise&&charSurprise();
  }, 800);
  if(typeof okiStartGameSupport==='function') okiStartGameSupport();
  if(typeof okiStartAutoPop==='function') okiStartAutoPop();
  _coinRainCount=0; startCoinRain();

  if(room.lang) window.speechSynthesis&&window.speechSynthesis.getVoices();
  // Tema butonunu göster ve sıfırla
  var _rtb = document.getElementById('_room-theme-btn');
  if(_rtb){ _rtb.style.display='flex'; }
  _resetRoomTheme();
}


