function evThemeName(id, fallback){
  var l=evValuesOn()?evValuesLang():'tr';
  var names={
    tr:{original:'Orijinal',warm:'Sicak Gunes',ocean:'Okyanus',forest:'Orman',candy:'Seker Dunyasi',mono:'Film Noir',neon:'Neon Gece',space:'Uzay',eduverse:'EduVerse',ice:'Buz Mavisi',rose:'Pembe Bulut',nebula:'Yesil Nebula',fire:'Turuncu Ates'},
    en:{original:'Original',warm:'Warm Sun',ocean:'Ocean',forest:'Forest',candy:'Candy World',mono:'Film Noir',neon:'Neon Night',space:'Space',eduverse:'EduVerse',ice:'Ice Blue',rose:'Pink Cloud',nebula:'Green Nebula',fire:'Orange Fire'},
    de:{original:'Original',warm:'Warme Sonne',ocean:'Ozean',forest:'Wald',candy:'Suessigkeitenwelt',mono:'Film Noir',neon:'Neonnacht',space:'Weltraum',eduverse:'EduVerse',ice:'Eisblau',rose:'Rosa Wolke',nebula:'Gruener Nebel',fire:'Oranges Feuer'},
    ar:{original:'الأصلي',warm:'شمس دافئة',ocean:'المحيط',forest:'الغابة',candy:'عالم الحلوى',mono:'فيلم نوار',neon:'ليلة نيون',space:'الفضاء',eduverse:'EduVerse',ice:'أزرق جليدي',rose:'سحابة وردية',nebula:'سديم أخضر',fire:'نار برتقالية'}
  };
  return (names[l]&&names[l][id])||fallback||id;
}
var ROOM_THEMES = [
  {id:'original', name:'Original', emoji:'\uD83C\uDFA8', filter:'none', gsBg:null},
  {id:'warm', name:'Warm Sun', emoji:'\u2600\uFE0F', filter:'hue-rotate(30deg) saturate(1.4) brightness(1.05)', gsBg:'rgba(80,20,0,.15)'},
  {id:'ocean', name:'Ocean', emoji:'\uD83C\uDF0A', filter:'hue-rotate(180deg) saturate(1.3) brightness(1.05)', gsBg:'rgba(0,20,60,.15)'},
  {id:'forest', name:'Forest', emoji:'\uD83C\uDF32', filter:'hue-rotate(90deg) saturate(1.4) brightness(.95)', gsBg:'rgba(0,40,10,.15)'},
  {id:'candy', name:'Candy World', emoji:'\uD83C\uDF6C', filter:'hue-rotate(300deg) saturate(1.6) brightness(1.1)', gsBg:'rgba(60,0,60,.15)'},
  {id:'mono', name:'Film Noir', emoji:'\uD83C\uDFAC', filter:'grayscale(0.75) contrast(1.1) brightness(1.05)', gsBg:'rgba(0,0,0,.1)'},
  {id:'neon', name:'Neon Night', emoji:'\uD83C\uDF03', filter:'hue-rotate(240deg) saturate(2) brightness(.9)', gsBg:'rgba(0,0,40,.2)'}
];
var _roomThemeIdx = 0;

function _applyRoomTheme(idx){
  _roomThemeIdx = idx % ROOM_THEMES.length;
  var th = ROOM_THEMES[_roomThemeIdx];
  var gc = document.getElementById('gc');
  if(gc) gc.style.filter = th.filter;
  var gs = document.getElementById('gs');
  if(gs && th.gsBg){
    gs.style.background = 'linear-gradient(180deg, ' + th.gsBg + ', transparent 60%)';
  } else if(gs){
    gs.style.background = '';
  }
  // Buton güncelle
  var btn = document.getElementById('_room-theme-btn');
  if(btn) btn.textContent = th.emoji;
  // Mini toast
  var t = document.createElement('div');
  t.className = '_gf';
  t.style.cssText = 'position:fixed;top:52px;left:50%;transform:translateX(-50%);z-index:9998;' +
    'background:rgba(0,0,0,.65);border:1px solid rgba(255,255,255,.15);border-radius:20px;' +
    'padding:5px 14px;font-family:Fredoka One;font-size:.75rem;color:rgba(255,255,255,.9);' +
    'pointer-events:none;white-space:nowrap;backdrop-filter:blur(4px);';
  t.textContent = th.emoji + ' ' + evThemeName(th.id,th.name);
  document.body.appendChild(t);
  setTimeout(function(){ t.style.opacity='0'; t.style.transition='opacity .5s'; setTimeout(function(){ if(t.parentNode) t.remove(); }, 500); }, 1500);
}

function _cycleRoomTheme(){
  _applyRoomTheme(_roomThemeIdx + 1);
}

function _resetRoomTheme(){
  _roomThemeIdx = 0;
  var gc = document.getElementById('gc');
  if(gc) gc.style.filter = 'none';
  var gs = document.getElementById('gs');
  if(gs) gs.style.background = '';
  var btn = document.getElementById('_room-theme-btn');
  if(btn) btn.textContent = String.fromCodePoint(0x1F3A8);
}


