var _raporTapCount = 0, _raporTapTimer = null;
var _qrTapCount = 0, _qrTapTimer = null;

function _raporTap(){
  _raporTapCount++;
  clearTimeout(_raporTapTimer);
  if(_raporTapCount >= 7){
    _raporTapCount = 0;
    showReport();
    return;
  }
  _raporTapTimer = setTimeout(function(){ _raporTapCount = 0; }, 800);
}

function _qrTap(){
  _qrTapCount++;
  clearTimeout(_qrTapTimer);
  if(_qrTapCount >= 7){
    _qrTapCount = 0;
    showParentQR();
    return;
  }
  _qrTapTimer = setTimeout(function(){ _qrTapCount = 0; }, 800);
}



