// Canvas events (after DOM ready)
function toggleFullscreen(){
  var el=document.getElementById('gs');
  if(!document.fullscreenElement){
    (el.requestFullscreen||el.webkitRequestFullscreen||el.mozRequestFullScreen).call(el);
    document.getElementById('gfs').textContent='✕';
  } else {
    (document.exitFullscreen||document.webkitExitFullscreen||document.mozCancelFullScreen).call(document);
    document.getElementById('gfs').textContent='⛶';
  }
}
document.addEventListener('fullscreenchange',function(){if(!document.fullscreenElement){var b=document.getElementById('gfs');if(b)b.textContent='⛶';}});
window.addEventListener('load',function(){
  // Puzzle canvas events
  var byc=document.getElementById('boy-canvas');
  if(byc){byc.addEventListener('touchstart',boyaStart,{passive:false});byc.addEventListener('touchmove',boyaDraw,{passive:false});byc.addEventListener('touchend',boyaEnd,{passive:false});byc.addEventListener('mousedown',boyaStart);byc.addEventListener('mousemove',function(e){if(boyaDrawing)boyaDraw(e);});byc.addEventListener('mouseup',boyaEnd);byc.addEventListener('mouseleave',boyaEnd);}
  var pzc=document.getElementById('pz-canvas');
  if(pzc){
    pzc.addEventListener('touchstart',puzzleDown,{passive:false});
    pzc.addEventListener('touchmove', puzzleMove,{passive:false});
    pzc.addEventListener('touchend',  puzzleUp,  {passive:false});
    pzc.addEventListener('mousedown', puzzleDown);
    pzc.addEventListener('mousemove', function(e){if(PUZZLE_DRAG)puzzleMove(e);});
    pzc.addEventListener('mouseup',   puzzleUp);
  }

  document.getElementById('acok').onclick=function(){document.getElementById('ach').classList.remove('show');};
  document.getElementById('gbk').onclick=function(){gameActive=false;goHome();};
  document.getElementById('bcyes').onclick=function(){document.getElementById('bc').classList.remove('show');goHome();};
  document.getElementById('bcno').onclick=function(){document.getElementById('bc').classList.remove('show');gameActive=true;};

  var gc=document.getElementById('gc');
  gc.addEventListener('click',function(e){
    if(!gameActive) return;
    var r=gc.getBoundingClientRect();
    tryPop(e.clientX-r.left,e.clientY-r.top);
  });
  gc.addEventListener('touchstart',function(e){
    if(!gameActive) return; e.preventDefault();
    var r=gc.getBoundingClientRect();
    Array.from(e.touches).forEach(function(t){tryPop(t.clientX-r.left,t.clientY-r.top);});
  },{passive:false});
});

