function getOkiStage(){
  var stage = OKI_STAGES[0];
  for(var i=0;i<OKI_STAGES.length;i++) if(totalScore>=OKI_STAGES[i].min) stage=OKI_STAGES[i];
  return stage;
}













function ctx_wing(c,x,y,sc,wf,col,flip){
  c.save(); c.translate(x,y);
  c.fillStyle=col+'55';
  c.beginPath(); c.ellipse(flip?18:-18,-8,22,14,flip?(wf+.3):(-.3-wf),0,Math.PI*2); c.fill();
  c.fillStyle=col+'33';
  c.beginPath(); c.ellipse(flip?14:-14,6,16,10,flip?(wf+.5):(-.5-wf),0,Math.PI*2); c.fill();
  c.restore();
}

function okiSpeak(){ charSpeak(); }

function showOkiBubble(msg){
  msg=evCleanOkiText(msg);
  // Her zaman güncel isimle değiştir
  var pn = playerName || '';
  if(msg && pn) msg = msg.replace(/_NU/g, pn.toUpperCase()).replace(/_N/g, pn);
  okiCurrentMsg=msg; okiMsgVisible=true;
  // Shop bubble (when shop is open)
  var shopBubble=document.getElementById('shop-bubble');
  if(shopBubble){
    shopBubble.innerHTML=msg+'<div style="position:absolute;bottom:-8px;left:14px;width:0;height:0;border-left:8px solid transparent;border-right:8px solid transparent;border-top:8px solid white;"></div>';
    shopBubble.style.display='block';
    shopBubble.style.animation='none';
    setTimeout(function(){shopBubble.style.animation='oki-fadein .3s ease';},10);
    clearTimeout(shopBubble._timer);
    shopBubble._timer=setTimeout(function(){shopBubble.style.display='none';},5000);
  }
  // Home screen bubble
  var el=document.getElementById('oki-bubble');
  if(el){ el.textContent=msg; el.style.opacity='1'; }
  var oc=document.getElementById('oki-canvas');
  if(oc){ oc.classList.add('oki-happy'); setTimeout(function(){oc.classList.remove('oki-happy');},500); }
  okiBouncing=true;
  // Karakter zıplasın
  if(typeof setCharState==='function') setCharState('jump',700);
  // Refleks odası bubble
  var rb=document.getElementById('refleks-oki-bubble');
  if(rb){
    rb.textContent=msg;
    rb.style.display='block';
    rb.style.animation='none';
    setTimeout(function(){rb.style.animation='oki-fadein .3s ease';},10);
    // Oki resmini güncelle
    var ri=document.getElementById('refleks-oki-img');
    if(ri && typeof _selectedChar!=='undefined'){
      var _stage=typeof getCurrentStage==='function'?getCurrentStage():null;
      var _key=_selectedChar==='kiz'?(_stage&&_stage.charSet?(_stage.charSet==='erkek_agac'?'kiz_agac':'kiz_fidan'):'kiz'):(_stage&&_stage.charSet||'erkek');
      var _imgs=_CHARS[_key]||_CHARS[_selectedChar]||_CHARS.erkek;
      ri.src=_imgs['idle']||'';
    }
  }
  // Game screen bubble
  var gb=document.getElementById('oki-game-bubble');
  if(gb){ gb.textContent=msg; gb.style.display='block'; gb.style.animation='none'; setTimeout(function(){gb.style.animation='oki-fadein .3s ease';},10); }
  clearTimeout(okiMsgTimer);
  okiMsgTimer=setTimeout(function(){
    okiMsgVisible=false; okiBouncing=false;
    var el2=document.getElementById('oki-bubble');
    if(el2) el2.style.opacity='0';
    var oc2=document.getElementById('oki-canvas');
    if(oc2) oc2.classList.remove('oki-happy');
    var gb2=document.getElementById('oki-game-bubble');
    if(gb2) gb2.style.display='none';
    var rb2=document.getElementById('refleks-oki-bubble');
    if(rb2) rb2.style.display='none';
  },3000);
}

function okiLevelUp(stage){
  showOkiBubble('Büyüdüm! Ben artık '+stage.name+'! 🎉');
  document.getElementById('oki-name').textContent=evEnglishOkiStageName(stage)+' '+String.fromCharCode(10022);
  for(var i=0;i<3;i++) setTimeout(function(){
    if(typeof burst==='function') burst(60+Math.random()*W*.3,100+Math.random()*80,'#FFD700',false);
  },i*300);
}

// Oki reacts to score
function okiReactToScore(pts){
  if(pts>=40){
    setCharState('jump', 2200);
    var bigMsgs=['WOW! '+pts+' puan! 🌟','MUHTEŞEM! 🏆','İNANILMAZ! ⚡','SEN DAHISIN! 🚀'];
    showOkiBubble(bigMsgs[Math.floor(Math.random()*bigMsgs.length)]);
    for(var _si=0;_si<6;_si++) setTimeout(_spawnSpark,_si*100);
    _charScreenShake();
  } else if(pts>=20){
    setCharState('jump', 1500);
    var midMsgs=['Süper! 🎉','Harika! ⭐','Devam et! 💪','Bravo! 🎊'];
    showOkiBubble(midMsgs[Math.floor(Math.random()*midMsgs.length)]);
    for(var _si2=0;_si2<3;_si2++) setTimeout(_spawnSpark,_si2*150);
  } else if(pts>0){
    if(Math.random()<.35){
      setCharState('wave', 1200);
      showOkiBubble(getOkiStage().msg[Math.floor(Math.random()*3)]);
    }
  }
}

function _charScreenShake(){
  var el=document.getElementById('char-main-img');
  if(!el) return;
  var orig=el.style.animation;
  el.style.animation='charShake .4s ease';
  setTimeout(function(){ el.style.animation=orig||'charFloat 3s ease-in-out infinite'; },500);
}

function _spawnSpark(){
  var el=document.getElementById('char-main-img');
  if(!el) return;
  var rect=el.getBoundingClientRect();
  var sp=document.createElement('div');
  sp.style.cssText='position:fixed;z-index:9999;pointer-events:none;font-size:'+(1+Math.random())+'rem;'
    +'left:'+(rect.left+rect.width/2+(Math.random()-.5)*60)+'px;'
    +'top:'+(rect.top+rect.height/2+(Math.random()-.5)*60)+'px;'
    +'animation:charSpark '+(0.7+Math.random()*.5)+'s ease forwards;';
  var sparks=['⭐','✨','🌟','💫','🎊','🎉'];
  sp.textContent=sparks[Math.floor(Math.random()*sparks.length)];
  document.body.appendChild(sp);
  setTimeout(function(){sp.remove();},1400);
}



