function getMelekSize(){
  var fed=JSON.parse(localStorage.getItem(_fedKey())||'{}');
  var streak=0;
  // Count days fed (skip today if not yet fed - don't punish)
  for(var i=1;i<=30;i++){
    var d=new Date(); d.setDate(d.getDate()-i);
    if(fed[d.toDateString()]) streak++;
    else break;
  }
  // Also count today if fed
  if(fed[new Date().toDateString()]) streak++;
  // Size: starts at 0.45, grows per day fed, max 1.0
  return Math.min(1.0, 0.45+streak*0.06);
}

function feedMelek(){
  var fed=JSON.parse(localStorage.getItem(_fedKey())||'{}');
  var today=new Date().toDateString();
  if(fed[today]){
    var alreadyFood=getTodayFood();
    showOkiBubble(evEnglishValuesActive()?'I already ate '+evEnglishFoodName(alreadyFood.name)+' today. Come back tomorrow!':(evValuesOn()&&evValuesLang()==='de'?'Heute habe ich schon '+evGermanFoodName(alreadyFood.name)+' gegessen. Komm morgen wieder!':'Bugun zaten '+alreadyFood.name+' yedim! Yarin gel!'));
    return;
  }
  fed[today]=true;
  localStorage.setItem(_fedKey(),JSON.stringify(fed));
  var food=getTodayFood();
  totalScore+=20; savePlayerData();
  document.getElementById('hsc').textContent=totalScore;
  updateLvl();
  showOkiBubble(evEnglishValuesActive()?'Yum! I ate '+evEnglishFoodName(food.name)+'! +20 stars':(evValuesOn()&&evValuesLang()==='de'?evGermanFoodName(food.name)+' gegessen! +20 Sterne':food.ico+' '+food.name+' yedim! +20'));
  setTimeout(function(){ initOki(); },600);
  for(var i=0;i<3;i++) setTimeout(function(){burst(60+Math.random()*100,120+Math.random()*60,'#FFD700',false);},i*200);
  playSpec();
}

function renderFoodButton(){
  var fed=JSON.parse(localStorage.getItem(_fedKey())||'{}');
  var today=new Date().toDateString();
  var food=getTodayFood();
  var btn=document.getElementById('feed-btn');
  if(!btn) return;
  if(fed[today]){
    btn.textContent=evEnglishValuesActive()?'Full today':(evValuesOn()&&evValuesLang()==='de'?'Satt':'Bugun yedim!');
    btn.style.opacity='0.5';
    btn.style.cursor='default';
  } else {
    btn.textContent=evValuesOn()&&evValuesLang()==='en'?'Feed: '+evEnglishFoodName(food.name):(evValuesOn()&&evValuesLang()==='fr'?'Nourrir: '+evEnglishFoodName(food.name):(evValuesOn()&&evValuesLang()==='de'?'Fuettern: '+evGermanFoodName(food.name):food.ico+' '+food.name+' ver!'));
    btn.style.opacity='1';
    btn.style.cursor='pointer';
  }
  btn.style.whiteSpace='normal';
  btn.style.lineHeight='1.1';
  btn.style.maxWidth='150px';
  // Update size label
  var size=getMelekSize();
  var days=Math.round((size-0.3)/0.07);
  var el=document.getElementById('oki-name');
  if(el){
    var stage=getOkiStage();
    el.textContent=evEnglishOkiStageName(stage)+' '+(evValuesOn()&&evValuesLang()==='en'?(days>0?'('+days+' days old)':'(newborn)'):(evValuesOn()&&evValuesLang()==='fr'?(days>0?'('+days+' jours)':'(tout petit)'):(evValuesOn()&&evValuesLang()==='de'?(days>0?'('+days+' Tage alt)':'(neu geboren)'):(days>0?'('+(days)+' gunluk)':'(yeni dogdu!)'))));
  }
}




// ── NEFES ODASI ──
function drawNefesOverlay(ts){
  var phaseLen=4800, t=ts%(phaseLen*4), phase=Math.floor(t/phaseLen), prog=(t%phaseLen)/phaseLen;
  var msgs=(evValuesOn()&&evValuesLang()==='en')?['Breathe in...','Hold...','Breathe out...','Rest...']:((evValuesOn()&&evValuesLang()==='de')?['Einatmen...','Halten...','Ausatmen...','Ruhen...']:((evValuesOn()&&evValuesLang()==='fr')?['Inspire...','Retiens...','Expire...','Repose-toi...']:((evValuesOn()&&evValuesLang()==='ar')?['\u0634\u0647\u064a\u0642...','\u0627\u062d\u0628\u0633...','\u0632\u0641\u064a\u0631...','\u0627\u0633\u062a\u0631\u062d...']:['Nefes Al...','Tut...','Nefes Ver...','Dinlen...'])));
  var col=['rgba(100,200,255,.7)','rgba(150,220,255,.5)','rgba(50,150,200,.7)','rgba(80,160,220,.5)'];
  var minR=W*.1, maxR=W*.2, r;
  if(phase===0) r=minR+(maxR-minR)*prog;
  else if(phase===1) r=maxR;
  else if(phase===2) r=maxR-(maxR-minR)*prog;
  else r=minR;
  var gw=ctx.createRadialGradient(W*.5,H*.4,r*.2,W*.5,H*.4,r*1.8);
  gw.addColorStop(0,col[phase]); gw.addColorStop(1,'transparent');
  ctx.fillStyle=gw; ctx.fillRect(0,0,W,H);
  for(var i=0;i<3;i++){
    ctx.strokeStyle=col[phase]; ctx.lineWidth=2-i*.5; ctx.globalAlpha=1-i*.25;
    ctx.beginPath(); ctx.arc(W*.5,H*.4,r+i*18,0,Math.PI*2); ctx.stroke(); ctx.globalAlpha=1;
  }
  ctx.fillStyle='rgba(200,240,255,.95)'; ctx.font='bold '+Math.round(W*.06)+'px Fredoka One'; ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText(msgs[phase],W*.5,H*.7);
  ctx.fillStyle='rgba(150,200,255,.5)'; ctx.font='bold '+Math.round(W*.03)+'px Nunito';
  ctx.fillText(evValuesOn()&&evValuesLang()==='en'?'Tap - collect points':(evValuesOn()&&evValuesLang()==='de'?'Tippen - Punkte sammeln':(evValuesOn()&&evValuesLang()==='fr'?'Touche - gagne des points':(evValuesOn()&&evValuesLang()==='ar'?'\u0627\u0644\u0645\u0633 - \u0627\u062c\u0645\u0639 \u0627\u0644\u0646\u0642\u0627\u0637':'Tikla - Puan Kazan'))),W*.5,H*.78);
}

// ── DOPAMİN ŞELALESI ──
var wdrops=[];
function drawWaterfall(ts){
  if(Math.random()<.35){
    wdrops.push({x:W*.25+Math.random()*W*.5,y:H*.05,vy:2+Math.random()*5,al:.8,r:Math.random()*7+2,col:['#4488FF','#44DDAA','#AA44FF','#FF4488','#44FFCC'][Math.floor(Math.random()*5)]});
  }
  wdrops=wdrops.filter(function(d){
    d.y+=d.vy; d.vy+=.1; d.al-=.007;
    if(d.al<=0||d.y>H) return false;
    ctx.save(); ctx.globalAlpha=d.al;
    var dg=ctx.createRadialGradient(d.x,d.y,0,d.x,d.y,d.r);
    dg.addColorStop(0,'rgba(255,255,255,.8)'); dg.addColorStop(.4,d.col+'cc'); dg.addColorStop(1,'transparent');
    ctx.fillStyle=dg; ctx.beginPath(); ctx.arc(d.x,d.y,d.r,0,Math.PI*2); ctx.fill();
    ctx.restore(); return true;
  });
}

