  var ta2=document.getElementById('dua-custom-txt');
  if(ta2) ta2.value='';
  // Go straight to seal
  ['dua-e1'].forEach(function(id){var el=document.getElementById(id);if(el)el.style.display='none';});
  document.getElementById('dc-ico').textContent='✍️';
  var _dlo = DUA_LANG_DATA[_duaLang]||DUA_LANG_DATA.tr;
  document.getElementById('dc-name').textContent=_dlo.myPrayer;
  document.getElementById('dc-ar').textContent='';
  document.getElementById('dc-tr').textContent=_selDua.tr;
  document.getElementById('dua-send-btn').style.display='block';
