function showBigGrowthScene(stage){
  var ov = document.getElementById('growth-big-ov');
  if(!ov) return;

  // Sahne içeriğini doldur
  var configs = {
    fidan: {
      emoji: '🌿',
      title: 'FİDAN OLDUN!',
      subtitle: 'Artık büyüdün!',
      msg_edu: 'Büyüdüm! Artık Fidanım! 🌿',
      msg_verse: 'Bakın büyüdüm! 🌿✨',
      color: '#44FF88',
      glow: 'rgba(50,220,100,.8)',
      bg: 'linear-gradient(160deg,#001a00,#002a00,#001a00)',
      stars: 50,
    },
    agac: {
      emoji: '🌳',
      title: 'AĞAÇ OLDUN!',
      subtitle: 'Tam güce ulaştın!',
      msg_edu: 'Ben artık bir Ağacım! 🌳💪',
      msg_verse: 'Ağaç oldum! Harika! 🌳✨',
      color: '#FFD700',
      glow: 'rgba(255,200,0,.8)',
      bg: 'linear-gradient(160deg,#0a0800,#150f00,#0a0800)',
      stars: 200,
    }
  };

  var cfg = configs[stage.id] || configs.fidan;

  // Arka plan
  ov.style.background = cfg.bg;
  ov.style.boxShadow = '0 0 100px ' + cfg.glow;

  // İçerik
  document.getElementById('gbig-emoji').textContent = cfg.emoji;
  document.getElementById('gbig-emoji').style.filter = 'drop-shadow(0 0 30px ' + cfg.glow + ')';
  document.getElementById('gbig-title').textContent = cfg.title;
  document.getElementById('gbig-title').style.color = cfg.color;
  document.getElementById('gbig-subtitle').textContent = cfg.subtitle;
  document.getElementById('gbig-stars').textContent = '+' + cfg.stars + ' ⭐ Büyüme Ödülü!';

  // Karakter
  var charKey = _selectedChar==='kiz'
    ? (stage.charSet==='erkek_agac'?'kiz_agac':'kiz_fidan')
    : (stage.charSet||'erkek');
  var imgs = _CHARS[charKey]||_CHARS[_selectedChar]||_CHARS.erkek;
  var ci = document.getElementById('gbig-char');
  if(ci) ci.src = imgs.idle||imgs[Object.keys(imgs)[0]];

  // Karakter konuşuyor
  var msg = _selectedChar==='kiz' ? cfg.msg_verse : cfg.msg_edu;
  document.getElementById('gbig-bubble').textContent = msg;

  // Konfeti
  var conf = document.getElementById('gbig-conf');
  conf.innerHTML = '';
  var colors = [cfg.color,'#FF8800','#88FF88','#88CCFF','#FF88CC','white'];
  for(var i=0;i<60;i++){
    var el=document.createElement('div');
    el.style.cssText='position:absolute;width:'+(5+Math.random()*8)+'px;height:'+(5+Math.random()*8)+'px;'+
      'border-radius:2px;left:'+Math.random()*100+'%;'+
      'background:'+colors[Math.floor(Math.random()*colors.length)]+';'+
      'animation:gbigConf '+(2+Math.random()*3)+'s linear '+(Math.random()*2)+'s infinite;';
    conf.appendChild(el);
  }

  // Göster
  ov.style.display = 'flex';

  // Ses efekti
  try{
    var ac=new(window.AudioContext||window.webkitAudioContext)();
    var notes=[[523,.1],[659,.1],[784,.1],[1047,.15],[1318,.2],[1047,.1],[1318,.3]];
    var t=ac.currentTime;
    notes.forEach(function(n,i){
      var o=ac.createOscillator();var g=ac.createGain();
      o.frequency.value=n[0];o.type='triangle';
      g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.15,t+.02);
      g.gain.exponentialRampToValueAtTime(.001,t+n[1]+.1);
      o.connect(g);g.connect(ac.destination);
      var d=notes.slice(0,i).reduce(function(s,x){return s+x[1];},0);
      o.start(t+d);o.stop(t+d+n[1]+.15);
    });
  }catch(e){}

  // Yıldız ödülü ver
  var cur=parseInt(localStorage.getItem('dei_total')||'0');
  savePlayerData();
}

function hideBigGrowthScene(){
  var ov=document.getElementById('growth-big-ov');
  if(ov) ov.style.display='none';
  document.getElementById('gbig-conf').innerHTML='';
  updateGrowthUI();
  setCharState('wave');
  setTimeout(function(){
    var msg = _selectedChar==='kiz'?'Büyümek harika! 🌟':'Büyüdüm! 💪🌟';
    showOkiBubble(msg);
  },500);
}

