function openRefleks(){
  var ov=document.getElementById('refleks-ov');
  if(ov){ov.style.display='block';rMenuye();evApplySpecialGerman();setTimeout(evApplySpecialGerman,80);}
  // Refleks Oki resmini ayarla
  var ri=document.getElementById('refleks-oki-img');
  if(ri && typeof _selectedChar!=='undefined' && typeof _CHARS!=='undefined'){
    var _stage=typeof getCurrentStage==='function'?getCurrentStage():null;
    var _key=_selectedChar==='kiz'?(_stage&&_stage.charSet?(_stage.charSet==='erkek_agac'?'kiz_agac':'kiz_fidan'):'kiz'):(_stage&&_stage.charSet||'erkek');
    var _imgs=_CHARS[_key]||_CHARS[_selectedChar]||_CHARS.erkek;
    ri.src=_imgs['idle']||'';
  }
  // Giriş mesajı
  setTimeout(function(){
    var girisMesajlari=(evValuesOn()&&evValuesLang()==='en')?['Reflex Room! Let us see how fast you are!','I like this room. Stay sharp and have fun!','Careful! This room is fast, but you can do it!','Ready? Focus on and go!']:((evValuesOn()&&evValuesLang()==='de')?['Reaktionsraum! Mal sehen, wie schnell du bist!','Ich mag diesen Raum. Bleib wach und hab Spass!','Achtung! Dieser Raum ist schnell, aber du schaffst das!','Bereit? Fokus an und los!']:['Refleks odasi mi? Bakalim neler yapabilirsin!','Bu odayi cok seviyorum. Sen de seveceksin!','Dikkat! Bu oda kolay degil!','Hazir misin? Baslayalim!']);
    showOkiBubble(girisMesajlari[Math.floor(Math.random()*girisMesajlari.length)]);
  }, 500);
}
function closeRefleks(){
  rTemizle();
  var ov=document.getElementById('refleks-ov');
  if(ov)ov.style.display='none';
  goHome();
}

