function rInit(){
  rGc=document.getElementById('refleks-gc');
  rCtx=rGc.getContext('2d');
  rW=rGc.width=rGc.offsetWidth||innerWidth;
  rH=rGc.height=rGc.offsetHeight||innerHeight;
  rStars=[];
  for(var i=0;i<100;i++)rStars.push({x:Math.random()*rW,y:Math.random()*rH,r:Math.random()*1.4+.3,a:Math.random(),t:Math.random()*6.28,s:.001+Math.random()*.002});
}

function rMenuye(){
  rTemizle();
  document.getElementById('refleks-menu').style.display='flex';
  document.getElementById('refleks-hud').style.display='none';
  document.getElementById('refleks-bitis').style.display='none';
  document.getElementById('refleks-talimat').style.display='none';
  document.getElementById('refleks-sira-wrap').style.display='none';
  // Menüdeyken canvas dokunmaları engelle
  var gc=document.getElementById('refleks-gc');
  if(gc){gc.style.pointerEvents='none';}
}

function rBasla(m){
  rTemizle(); // Önceki modun tüm timer ve objelerini temizle
  rInit();
  rMod=m;rSkor=0;rSure=60;rObjs=[];rParts=[];rHayvan=null;rHayvanHiz=4.5;
  rSiraObjs=[];rSiraBeklenen=0;_rCommentCount=0;
  document.getElementById('refleks-menu').style.display='none';
  document.getElementById('refleks-hud').style.display='flex';
  document.getElementById('refleks-bitis').style.display='none';
  document.getElementById('refleks-talimat').style.display='none';
  document.getElementById('refleks-sira-wrap').style.display='none';
  document.getElementById('refleks-sira-wrap').innerHTML='';
  // Oyun modunda canvas dokunmaları aktif
  var gc2=document.getElementById('refleks-gc');
  if(gc2){gc2.style.pointerEvents='auto';}
  document.getElementById('rh-skor').textContent='0';
  document.getElementById('rh-sure').textContent='60';
  document.getElementById('rh-sure').style.color='#FF6B6B';
  document.getElementById('refleks-pb').style.width='100%';
  document.getElementById('rh-mod').textContent=(evValuesOn()&&evValuesLang()==='en'?{isik:'Light',renk:'Color',hayvan:'Target',sira:'Sequence',kaybolan:'Disappearing',bomba:'Bomb',buyuk:'Biggest'}:(evValuesOn()&&evValuesLang()==='de'?{isik:'Licht',renk:'Farbe',hayvan:'Ziel',sira:'Reihenfolge',kaybolan:'Verschwindend',bomba:'Bombe',buyuk:'Groesster'}:{isik:'Light',renk:'Color',hayvan:'Target',sira:'Sequence',kaybolan:'Disappearing',bomba:'Bomb',buyuk:'Biggest'}))[m];

  if(m==='renk')rRenkBasla();
  else if(m==='hayvan')rHayvanBasla();
  else if(m==='sira')rSiraBasla();
  else if(m==='kaybolan')rKaybolanBasla();
  else if(m==='bomba')rBombaBasla();
  else if(m==='buyuk')rBuyukBasla();
  else rIsikBasla();

  rSureInt=setInterval(function(){
    rSure--;
    document.getElementById('rh-sure').textContent=rSure;
    document.getElementById('refleks-pb').style.width=(rSure/60*100)+'%';
    if(rSure<=10)document.getElementById('rh-sure').style.color='#FF3333';
    if(rSure<=0){clearInterval(rSureInt);rBitis();}
  },1000);

  rGc.ontouchstart=function(e){e.preventDefault();Array.from(e.changedTouches).forEach(function(t){rDokunma(t.clientX,t.clientY);});};
  rGc.onmousedown=function(e){rDokunma(e.clientX,e.clientY);};
  rAnimId=requestAnimationFrame(rLoop);
}

function rLoop(){
  if(!rMod||!rCtx) return; // Temizlendiyse dur
  rCtx.clearRect(0,0,rW,rH);
  var g=rCtx.createLinearGradient(0,0,0,rH);
  g.addColorStop(0,'#060d1a');g.addColorStop(1,'#0a1628');
  rCtx.fillStyle=g;rCtx.fillRect(0,0,rW,rH);
  rStars.forEach(function(s){s.t+=s.s;s.a=.08+Math.abs(Math.sin(s.t))*.45;rCtx.globalAlpha=s.a;rCtx.fillStyle='#8899BB';rCtx.beginPath();rCtx.arc(s.x,s.y,s.r,0,Math.PI*2);rCtx.fill();});
  rCtx.globalAlpha=1;

  if(rMod==='isik')rIsikGuncelle();
  else if(rMod==='renk')rRenkGuncelle();
  else if(rMod==='hayvan')rHayvanGuncelle();
  else if(rMod==='sira')rSiraGuncelle();
  else if(rMod==='kaybolan')rKaybolanGuncelle();
  else if(rMod==='bomba')rBombaGuncelle();
  else if(rMod==='buyuk')rBuyukGuncelle();

  rParts.forEach(function(p){p.x+=p.vx;p.y+=p.vy;p.vy+=.1;p.al-=.035;p.r*=.94;if(p.al<.02)return;rCtx.globalAlpha=p.al;rCtx.fillStyle=p.col;rCtx.beginPath();rCtx.arc(p.x,p.y,p.r,0,Math.PI*2);rCtx.fill();});
  rParts=rParts.filter(function(p){return p.al>=.02;});
  rCtx.globalAlpha=1;
  rAnimId=requestAnimationFrame(rLoop);
}

function rDaireCiz(o){
  if(!o.alive)return;
  o.scale=Math.min(1,(o.scale||0)+.15);o.puls=(o.puls||0)+.08;
  var r=o.r*o.scale;
  rCtx.save();rCtx.translate(o.x,o.y);
  var gl=rCtx.createRadialGradient(0,0,0,0,0,r*2.5);
  gl.addColorStop(0,o.col+'33');gl.addColorStop(1,'transparent');
  rCtx.fillStyle=gl;rCtx.fillRect(-r*2.5,-r*2.5,r*5,r*5);
  var bg=rCtx.createRadialGradient(-r*.3,-r*.3,r*.08,0,0,r);
  bg.addColorStop(0,'rgba(255,255,255,.35)');bg.addColorStop(.35,o.col);bg.addColorStop(1,o.col+'99');
  rCtx.fillStyle=bg;rCtx.beginPath();rCtx.arc(0,0,r,0,Math.PI*2);rCtx.fill();
  if(o.maxLife){var ratio=o.life/o.maxLife;rCtx.strokeStyle='rgba(255,255,255,.2)';rCtx.lineWidth=3;rCtx.beginPath();rCtx.arc(0,0,r+5,-Math.PI/2,-Math.PI/2+ratio*Math.PI*2);rCtx.stroke();}
  if(o.label){rCtx.font='bold '+Math.round(r*.65)+'px Fredoka One,sans-serif';rCtx.fillStyle='rgba(255,255,255,.9)';rCtx.textAlign='center';rCtx.textBaseline='middle';rCtx.fillText(o.label,0,0);}
  if(o.emoji){rCtx.font=Math.round(r*1.2)+'px serif';rCtx.textAlign='center';rCtx.textBaseline='middle';rCtx.fillText(o.emoji,0,0);}
  rCtx.restore();
}

function rPatlat(x,y,col,dogru,isBomba){
  var c=dogru?col:'#FF3333';
  var pcnt=isBomba?28:14;
  for(var i=0;i<pcnt;i++){
    var a=Math.random()*Math.PI*2,s=(isBomba?5:3)+Math.random()*(isBomba?10:7);
    rParts.push({x:x,y:y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-2,r:(isBomba?4:3)+Math.random()*(isBomba?7:5),al:1,col:isBomba?(['#FF8800','#FF4400','#FFDD00','#FF6600'][Math.floor(Math.random()*4)]):c});
  }
  try{
    var ac=new(window.AudioContext||window.webkitAudioContext)();
    if(isBomba&&dogru){
      // Bomba patlaması — derin boom + crackle
      var buf=ac.createBuffer(1,ac.sampleRate*.5,ac.sampleRate);
      var d=buf.getChannelData(0);
      for(var i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,1.5);
      var src=ac.createBufferSource(),g0=ac.createGain();
      var lf=ac.createBiquadFilter();lf.type='lowpass';lf.frequency.value=180;
      src.buffer=buf;g0.gain.value=1.2;
      src.connect(lf);lf.connect(g0);g0.connect(ac.destination);src.start();
      // Derin bas darbe
      var o0=ac.createOscillator(),g00=ac.createGain();
      o0.type='sine';o0.frequency.setValueAtTime(80,ac.currentTime);
      o0.frequency.exponentialRampToValueAtTime(30,ac.currentTime+.3);
      g00.gain.setValueAtTime(.9,ac.currentTime);g00.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.45);
      o0.connect(g00);g00.connect(ac.destination);o0.start();o0.stop(ac.currentTime+.45);
      // Crackle
      var o1=ac.createOscillator(),g01=ac.createGain();
      o1.type='sawtooth';o1.frequency.setValueAtTime(400,ac.currentTime);
      o1.frequency.exponentialRampToValueAtTime(50,ac.currentTime+.2);
      g01.gain.setValueAtTime(.3,ac.currentTime);g01.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.25);
      o1.connect(g01);g01.connect(ac.destination);o1.start();o1.stop(ac.currentTime+.25);
    } else if(dogru){
      [440,550,660].forEach(function(f,i){var o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.07,ac.currentTime+i*.04);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+i*.04+.13);o.connect(g);g.connect(ac.destination);o.start(ac.currentTime+i*.04);o.stop(ac.currentTime+i*.04+.13);});
    } else {
      var o2=ac.createOscillator(),g2=ac.createGain();o2.type='sawtooth';o2.frequency.setValueAtTime(200,ac.currentTime);o2.frequency.exponentialRampToValueAtTime(60,ac.currentTime+.22);g2.gain.setValueAtTime(.08,ac.currentTime);g2.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.22);o2.connect(g2);g2.connect(ac.destination);o2.start();o2.stop(ac.currentTime+.22);
    }
  }catch(e){}
}

function rFlash(col){var f=document.getElementById('refleks-flash');f.style.background=col;f.style.opacity='1';setTimeout(function(){f.style.opacity='0';},100);}
var _rCommentCount=0;
function rEkle(pts){
  rSkor=Math.max(0,rSkor+pts);
  document.getElementById('rh-skor').textContent=rSkor;
  _rCommentCount++;
  // Her 5 hamlede bir şakacı yorum
  if(_rCommentCount%5===0){
    var positiveComments=(evValuesOn()&&evValuesLang()==='en')?['A little faster!','Nice reflex!','That was sharp!','Yes, that worked!','Keep going!']:((evValuesOn()&&evValuesLang()==='de')?['Etwas schneller!','Starke Reaktion!','Das war wach!','Ja, das passt!','Weiter so!']:['Hizlan biraz!','Guzel refleks!','Devam devam!']);
    var negativeComments=(evValuesOn()&&evValuesLang()==='en')?['Wrong one, try again!','Careful, look closely!','Almost, stay calm!','Slow down and focus!']:((evValuesOn()&&evValuesLang()==='de')?['Falsch, versuch es nochmal!','Vorsicht, genau schauen!','Fast, bleib ruhig!','Langsamer und fokussiert!']:['Yanlis! Tekrar dene!','Dikkat et!','Sakin ol!']);
    var msg = pts>0 ? positiveComments[Math.floor(Math.random()*positiveComments.length)] : negativeComments[Math.floor(Math.random()*negativeComments.length)];
    showOkiBubble(msg);
  }
}
function rAktif(){return rSure>0;}
function rSpawnPos(){var m=55;return{x:m+Math.random()*(rW-m*2),y:80+m+Math.random()*(rH-m*2-80)};}

// ISIK VUR
function rIsikBasla(){
  // Dinamik interval — sure azaldıkça hızlanır
  function spawnIsik(){
    if(!rMod||!rAktif())return;
    if(rObjs.filter(function(o){return o.type==='isik';}).length>=8)return;
    var p=rSpawnPos();
    var cols=['#FFD700','#FF6B6B','#44AAFF','#AA44FF','#44FF88','#FF8844'];
    var c=cols[Math.floor(Math.random()*cols.length)];
    var life=Math.max(30,75-(60-rSure)*1.4); // hızla azalır
    rObjs.push({type:'isik',x:p.x,y:p.y,r:22+Math.random()*18,col:c,alive:true,scale:0,puls:0,life:life,maxLife:life});
    // Bir sonraki spawn süresini dinamik hesapla
    var nextMs=Math.max(150,600-(60-rSure)*10);
    rSpawnTimers.push(setTimeout(spawnIsik,nextMs));
  }
  rSpawnTimers.push(setTimeout(spawnIsik,400));
}
function rIsikGuncelle(){rObjs.forEach(function(o){if(o.type!=='isik')return;rDaireCiz(o);o.life--;if(o.life<=0)o.alive=false;});rObjs=rObjs.filter(function(o){return o.alive;});}

// RENK BUL
function rRenkBasla(){document.getElementById('refleks-talimat').style.display='block';rYeniRenkSoru();rSpawnTimers.push(setInterval(function(){if(!rAktif())return;if(rObjs.filter(function(o){return o.type==='renk';}).length>=5)return;var p=rSpawnPos();var ri=Math.floor(Math.random()*R_RENKLER.length);var life=Math.max(60,130-(60-rSure)*1.8);rObjs.push({type:'renk',x:p.x,y:p.y,r:28+Math.random()*14,col:R_RENKLER[ri].col,ad:R_RENKLER[ri].ad,alive:true,scale:0,puls:0,life:life,maxLife:life});},Math.max(500,900-(60-rSure)*7)));}
function rYeniRenkSoru(){rRenkHedef=R_RENKLER[Math.floor(Math.random()*R_RENKLER.length)];var prompt=(evValuesOn()&&evValuesLang()==='en')?'Tap: ':((evValuesOn()&&evValuesLang()==='de')?'Tippe: ':'Dokun: ');var colorName=(evValuesOn()&&evValuesLang()==='en')?(window.eduverseEnglishClean?window.eduverseEnglishClean(rRenkHedef.ad):rRenkHedef.ad):((evValuesOn()&&evValuesLang()==='de')?(rRenkHedef.de||rRenkHedef.ad):rRenkHedef.ad);document.getElementById('refleks-talimat').innerHTML='<div style="background:rgba(0,0,0,.6);border-radius:16px;padding:8px 20px;font-family:Fredoka One,sans-serif;font-size:1.4rem;"><span style="color:rgba(255,255,255,.5);font-size:.9rem;">'+prompt+'</span><span style="color:'+rRenkHedef.col+';text-shadow:0 0 15px '+rRenkHedef.col+';">'+colorName+'</span></div>';}
function rRenkGuncelle(){rObjs.forEach(function(o){if(o.type!=='renk')return;rDaireCiz(o);o.life--;if(o.life<=0)o.alive=false;});rObjs=rObjs.filter(function(o){return o.alive;});}

// HAYVAN YAKALA
function rHayvanBasla(){rYeniHayvan();}
function rYeniHayvan(){var k=Math.floor(Math.random()*4),h=rHayvanHiz,x,y,vx,vy;if(k===0){x=Math.random()*rW;y=-50;vx=(Math.random()-.5)*h;vy=h+Math.random();}else if(k===1){x=rW+50;y=80+Math.random()*(rH-80);vx=-(h+Math.random());vy=(Math.random()-.5)*h;}else if(k===2){x=Math.random()*rW;y=rH+50;vx=(Math.random()-.5)*h;vy=-(h+Math.random());}else{x=-50;y=80+Math.random()*(rH-80);vx=h+Math.random();vy=(Math.random()-.5)*h;}var hr=Math.max(16,26-(60-rSure)*.2);rHayvan={x:x,y:y,vx:vx,vy:vy,emoji:R_HAYVANLAR[Math.floor(Math.random()*R_HAYVANLAR.length)],r:hr,alive:true};}
function rHayvanGuncelle(){if(!rHayvan)return;rHayvan.x+=rHayvan.vx;rHayvan.y+=rHayvan.vy;if(rHayvan.x<-70||rHayvan.x>rW+70||rHayvan.y<-70||rHayvan.y>rH+70){rYeniHayvan();return;}rCtx.save();rCtx.translate(rHayvan.x,rHayvan.y);var gl=rCtx.createRadialGradient(0,0,0,0,0,rHayvan.r*2);gl.addColorStop(0,'rgba(255,215,0,.15)');gl.addColorStop(1,'transparent');rCtx.fillStyle=gl;rCtx.fillRect(-rHayvan.r*2,-rHayvan.r*2,rHayvan.r*4,rHayvan.r*4);rCtx.font=(rHayvan.r*1.8)+'px serif';rCtx.textAlign='center';rCtx.textBaseline='middle';rCtx.fillText(rHayvan.emoji,0,0);rCtx.restore();}

// SIRA TAKİP
function rSiraBasla(){var sw=document.getElementById('refleks-sira-wrap');sw.style.display='flex';rYeniSira();}
function rYeniSira(){rSiraBeklenen=0;var pz=[[rW*.2,rH*.32],[rW*.5,rH*.28],[rW*.8,rH*.32],[rW*.2,rH*.62],[rW*.5,rH*.68],[rW*.8,rH*.62]];rObjs=rObjs.filter(function(o){return o.type!=='sira';});rSiraObjs=[];var nums=[1,2,3,4,5,6];nums.sort(function(){return Math.random()-.5;});var sw=document.getElementById('refleks-sira-wrap');sw.innerHTML='';for(var i=0;i<6;i++){var dot=document.createElement('div');dot.className='rsd';sw.appendChild(dot);var o={type:'sira',x:pz[i][0],y:pz[i][1],r:30,num:nums[i],col:'#5544EE',alive:true,scale:0,puls:0,label:''+nums[i],basildi:false};rObjs.push(o);rSiraObjs.push(o);}}
function rSiraGuncelle(){rSiraObjs.forEach(function(o){if(!o.alive)return;o.col=(!o.basildi&&o.num===rSiraBeklenen+1)?'#FFD700':'#5544EE';rDaireCiz(o);});}

// KAYBOLAN
function rKaybolanBasla(){rSpawnTimers.push(setInterval(function(){if(!rAktif())return;var p=rSpawnPos();var cols=['#FF6B6B','#FFD700','#44CCFF','#AA66FF','#44FF88'];var life=Math.max(18,35-(60-rSure)*.4);rObjs.push({type:'kaybolan',x:p.x,y:p.y,r:26+Math.random()*16,col:cols[Math.floor(Math.random()*cols.length)],alive:true,scale:0,puls:0,life:life,maxLife:life});},Math.max(500,1000-(60-rSure)*8)));}
function rKaybolanGuncelle(){rObjs.forEach(function(o){if(o.type!=='kaybolan')return;if(o.life<12){var sh=3;o.x+=(-sh+Math.random()*sh*2);o.y+=(-sh+Math.random()*sh*2);}rDaireCiz(o);o.life--;if(o.life<=0)o.alive=false;});rObjs=rObjs.filter(function(o){return o.alive;});}

// BOMBA
function rBombaBasla(){document.getElementById('refleks-talimat').style.display='block';document.getElementById('refleks-talimat').innerHTML='<div style="background:rgba(0,0,0,.6);border-radius:16px;padding:6px 18px;font-family:Fredoka One,sans-serif;font-size:1rem;color:rgba(255,255,255,.7);">'+(evValuesOn()&&evValuesLang()==='en'?'Tap bombs | Avoid stars!':(evValuesOn()&&evValuesLang()==='de'?'Bombe antippen | Sterne meiden!':'Bombaya dokun | Yildizdan kac!'))+'</div>';rSpawnTimers.push(setInterval(function(){if(!rAktif())return;if(rObjs.filter(function(o){return o.type==='bomba';}).length>=7)return;var p=rSpawnPos();var isBomba=Math.random()<.4;var blife=Math.max(55,110-(60-rSure)*1.5);rObjs.push({type:'bomba',x:p.x,y:p.y,r:24+Math.random()*14,col:isBomba?'#444455':'#FFD700',emoji:isBomba?'💣':'⭐',isBomba:isBomba,alive:true,scale:0,puls:0,life:blife,maxLife:blife});},Math.max(380,750-(60-rSure)*7)));}
function rBombaGuncelle(){rObjs.forEach(function(o){if(o.type!=='bomba')return;rDaireCiz(o);o.life--;if(o.life<=0)o.alive=false;});rObjs=rObjs.filter(function(o){return o.alive;});}

// BÜYÜĞÜ BUL
function rBuyukBasla(){document.getElementById('refleks-talimat').style.display='block';document.getElementById('refleks-talimat').innerHTML='<div style="background:rgba(0,0,0,.6);border-radius:16px;padding:6px 18px;font-family:Fredoka One,sans-serif;font-size:1rem;color:rgba(255,255,255,.7);">'+(evValuesOn()&&evValuesLang()==='en'?'Tap the biggest circle!':(evValuesOn()&&evValuesLang()==='de'?'Tippe den groessten Kreis!':'En buyuk daireye dokun!'))+'</div>';setTimeout(function(){rYeniBuyuk();rBuyukTimer=setInterval(rYeniBuyuk,2400);},80);}
function rYeniBuyuk(){if(!rAktif())return;rObjs=rObjs.filter(function(o){return o.type!=='buyuk';});var pz=[[rW*.2,rH*.36],[rW*.5,rH*.28],[rW*.8,rH*.38],[rW*.35,rH*.65],[rW*.65,rH*.65]];pz.sort(function(){return Math.random()-.5;});var cols=['#FF6B6B','#4488FF','#44CC66','#AA44FF','#FFD700'];var temel=Math.min(rW,rH)*.055;var carp=[.55,.75,.9,1.35];carp.sort(function(){return Math.random()-.5;});var maxI=0,maxR=0;for(var i=0;i<4;i++){var r=Math.round(temel*carp[i]);if(r>maxR){maxR=r;maxI=i;}}for(var j=0;j<4;j++){rObjs.push({type:'buyuk',x:pz[j][0],y:pz[j][1],r:Math.round(temel*carp[j]),col:cols[j%cols.length],alive:true,scale:0,puls:0,isBuyuk:j===maxI,life:Math.max(80,130-(60-rSure)*1.2),maxLife:130});}}
function rBuyukGuncelle(){rObjs.forEach(function(o){if(o.type!=='buyuk')return;rDaireCiz(o);o.life--;if(o.life<=0)o.alive=false;});rObjs=rObjs.filter(function(o){return o.alive;});}

// DOKUNMA
function rDokunma(px,py){
  if(rMod==='renk'){rObjs.forEach(function(o){if(!o.alive||o.type!=='renk')return;var dx=px-o.x,dy=py-o.y;if(Math.sqrt(dx*dx+dy*dy)<o.r+14){if(o.ad===rRenkHedef.ad){rPatlat(o.x,o.y,o.col,true);rEkle(25);o.alive=false;rFlash('rgba(255,215,0,.1)');rYeniRenkSoru();}else{rPatlat(o.x,o.y,o.col,false);rEkle(-8);o.alive=false;rFlash('rgba(255,0,0,.2)');}}});}
  else if(rMod==='hayvan'){if(!rHayvan)return;var dx=px-rHayvan.x,dy=py-rHayvan.y;if(Math.sqrt(dx*dx+dy*dy)<rHayvan.r+22){rPatlat(rHayvan.x,rHayvan.y,'#FFD700',true);rEkle(30);rFlash('rgba(255,215,0,.15)');rHayvanHiz=Math.min(14,rHayvanHiz+.9);rYeniHayvan();}}
  else if(rMod==='sira'){rSiraObjs.forEach(function(o){if(!o.alive||o.basildi)return;var dx=px-o.x,dy=py-o.y;if(Math.sqrt(dx*dx+dy*dy)<o.r+14){if(o.num===rSiraBeklenen+1){o.basildi=true;o.alive=false;rPatlat(o.x,o.y,'#44FF88',true);rEkle(20);var d=document.getElementById('refleks-sira-wrap').children;if(d[rSiraBeklenen])d[rSiraBeklenen].classList.add('ok');rSiraBeklenen++;if(rSiraBeklenen>=6){rEkle(40);rFlash('rgba(255,215,0,.2)');setTimeout(rYeniSira,500);}}else{rPatlat(o.x,o.y,'#FF4444',false);rEkle(-20);rFlash('rgba(255,0,0,.3)');var d2=document.getElementById('refleks-sira-wrap').children;Array.from(d2).forEach(function(x){x.classList.add('hata');});setTimeout(rYeniSira,700);}}});}
  else if(rMod==='bomba'){rObjs.forEach(function(o){if(!o.alive||o.type!=='bomba')return;var dx=px-o.x,dy=py-o.y;if(Math.sqrt(dx*dx+dy*dy)<o.r+14){o.alive=false;if(o.isBomba){rPatlat(o.x,o.y,'#FF8844',true,true);rEkle(25);rFlash('rgba(255,140,0,.25)');}else{rPatlat(o.x,o.y,'#FFD700',false,false);rEkle(-15);rFlash('rgba(255,0,0,.25)');}}});}
  else if(rMod==='buyuk'){rObjs.forEach(function(o){if(!o.alive||o.type!=='buyuk')return;var dx=px-o.x,dy=py-o.y;if(Math.sqrt(dx*dx+dy*dy)<o.r+12){o.alive=false;if(o.isBuyuk){rPatlat(o.x,o.y,o.col,true);rEkle(30);rFlash('rgba(255,215,0,.18)');rObjs.forEach(function(ob){if(ob.type==='buyuk')ob.alive=false;});setTimeout(rYeniBuyuk,400);}else{rPatlat(o.x,o.y,'#FF4444',false);rEkle(-12);rFlash('rgba(255,0,0,.2)');}}});}
  else{var hit=false;rObjs.forEach(function(o){if(!o.alive)return;var dx=px-o.x,dy=py-o.y;if(Math.sqrt(dx*dx+dy*dy)<o.r+12){rPatlat(o.x,o.y,o.col,true);rEkle(20);o.alive=false;hit=true;rFlash('rgba(255,215,0,.1)');}}); if(!hit&&rMod==='isik'){rEkle(-3);rFlash('rgba(255,0,0,.12)');}}
}

