function openSinema(){
  var isKiz = _selectedChar === 'kiz';
  var _eduImgs = ['data:image/png;base64,','data:image/png;base64,','data:image/png;base64,','data:image/png;base64,','data:image/png;base64,'];
  var _kizImgs = ['data:image/png;base64,','data:image/png;base64,','data:image/png;base64,','data:image/png;base64,','data:image/png;base64,'];
  var imgs = isKiz ? _kizImgs : _eduImgs;
  var subs = _snValuesEn() ? _snEnglishSubs(isKiz) : (_snValuesDe() ? _snGermanSubs(isKiz) : (_snValuesFr() ? _snFrenchSubs(isKiz) : (_snValuesAr() ? _snArabicSubs(isKiz) : (isKiz ? _snVSubs : _snESubs))));
  var bgs  = isKiz ? _snVBgs  : _snEBgs;
  _snSS = [];
  for(var i=0;i<8;i++) _snSS.push({bg:bgs[i], img:imgs[i<imgs.length?i:imgs.length-1], sub:subs[i]});
  document.getElementById('hm').style.display = 'none';
  document.getElementById('sn-ov').style.display = 'flex';
  evApplyCinemaGerman();
  var ch = document.getElementById('sn-ch');
  _snSC = 0;
  _snGo(0);
  _snMuzik();
  _snPop(20);
  setTimeout(function(){ _snPop(15); }, 1500);
  if(_snST) clearInterval(_snST);
  _snST = setInterval(function(){ _snGo((_snSC+1)%8); }, 4500);
}

function closeSinema(){
  if(_snST){ clearInterval(_snST); _snST = null; }
  _snStopMuzik();
  document.getElementById('sn-ov').style.display = 'none';
  document.getElementById('hm').style.display = 'flex';
}

function _snGo(i){
  _snSC = i;
  var s = _snSS[i]; if(!s) return;
  _snPlayAudio();
  // Patlama efekti!
  _snBurst();
  if(i===7){ _snBirthday(); }
  var e;
  e = document.getElementById('sn-bg'); if(e) e.style.background = s.bg;
  e = document.getElementById('sn-ch');
  if(e){ e.src=s.img; e.style.opacity='1'; }
  e = document.getElementById('sn-tx');
  if(e){ e.textContent=s.sub; e.style.opacity='1'; }
  document.querySelectorAll('.sndot').forEach(function(d,j){
    d.style.background = j===i ? '#FF3366' : 'rgba(255,255,255,.3)';
  });
  _snPop(12);
  if(i===7) _snPop(40);
}

function _snPop(n){
  var r = document.getElementById('sn-rn'); if(!r) return;
  for(var i=0;i<n;i++){
    (function(){
      var el = document.createElement('span');
      el.textContent = ['🍿','⭐','✨','🌟','🎬'][Math.floor(Math.random()*5)];
      el.style.cssText = 'position:absolute;font-size:1.4rem;left:'+Math.random()*90+'%;top:-30px;animation:snpc '+(1.5+Math.random()*2)+'s ease-in '+(Math.random()*0.5)+'s both;pointer-events:none;';
      r.appendChild(el);
      setTimeout(function(){ el.remove(); }, 5000);
    })();
  }
}

function _snMuz(){
  try{
    var A = getAC();
    var ns = [[392,.18],[494,.18],[587,.18],[698,.22],[587,.1],[494,.1],[587,.3]];
    var t = A.currentTime;
    ns.forEach(function(n,i){
      var o = A.createOscillator(), g = A.createGain();
      o.type = 'triangle'; o.frequency.value = n[0];
      var d = ns.slice(0,i).reduce(function(s,x){ return s+x[1]; },0);
      g.gain.setValueAtTime(0,t+d);
      g.gain.linearRampToValueAtTime(.12,t+d+.04);
      g.gain.exponentialRampToValueAtTime(.001,t+d+n[1]);
      o.connect(g); g.connect(A.destination);
      o.start(t+d); o.stop(t+d+n[1]+.1);
    });
  }catch(e){}
}

function _snBurst(){
  var r = document.getElementById('sn-rn'); if(!r) return;
  var W = r.offsetWidth || 360;
  var H = r.offsetHeight || 640;
  var emojis = ['🍿','⭐','✨','🌟','🎬','💥','🎊','🎉','💫','🏆'];
  for(var i=0;i<30;i++){
    (function(){
      var el = document.createElement('div');
      el.textContent = emojis[Math.floor(Math.random()*emojis.length)];
      var startX = W * (0.2 + Math.random()*0.6);
      var startY = H * (0.3 + Math.random()*0.4);
      var angle = Math.random() * Math.PI * 2;
      var speed = 80 + Math.random() * 150;
      var endX = startX + Math.cos(angle) * speed;
      var endY = startY + Math.sin(angle) * speed;
      el.style.cssText = 'position:absolute;font-size:'+(1+Math.random()*0.8)+'rem;'+
        'left:'+startX+'px;top:'+startY+'px;'+
        'transition:all '+(0.4+Math.random()*0.6)+'s ease-out;'+
        'pointer-events:none;z-index:95;opacity:1;';
      r.appendChild(el);
      requestAnimationFrame(function(){
        requestAnimationFrame(function(){
          el.style.left = endX + 'px';
          el.style.top = endY + 'px';
          el.style.opacity = '0';
          el.style.transform = 'scale(0.3) rotate('+(Math.random()*360)+'deg)';
        });
      });
      setTimeout(function(){ el.remove(); }, 1200);
    })();
  }
  // Ses
  try{
    var A=getAC();
    [[523,.08],[659,.06],[784,.08],[1047,.12]].forEach(function(n,i){
      var o=A.createOscillator(),g=A.createGain();
      o.type='triangle';o.frequency.value=n[0];
      g.gain.setValueAtTime(.15,A.currentTime+i*.06);
      g.gain.exponentialRampToValueAtTime(.001,A.currentTime+i*.06+n[1]);
      o.connect(g);g.connect(A.destination);
      o.start(A.currentTime+i*.06);o.stop(A.currentTime+i*.06+n[1]+.05);
    });
  }catch(e){}
}

function _snBirthday(){
  var r=document.getElementById('sn-rn');if(!r)return;
  var items=['🎂','🕯️','🎉','🎊','🌟','🎈','🥳','🎁','✨','💛','💕','⭐','🎀','🍰','🎆'];
  for(var i=0;i<60;i++){
    (function(idx){
      setTimeout(function(){
        var el=document.createElement('div');
        el.textContent=items[Math.floor(Math.random()*items.length)];
        el.style.cssText='position:absolute;font-size:'+(1.2+Math.random()*1.5)+'rem;'+
          'left:'+Math.random()*95+'%;top:-40px;'+
          'animation:snpc '+(1.5+Math.random()*2.5)+'s ease-in both;'+
          'pointer-events:none;z-index:96;';
        r.appendChild(el);
        setTimeout(function(){el.remove();},4500);
      }, idx*50);
    })(i);
  }
  // Sesli konuşma - 3 cümle art arda
  if(!window.speechSynthesis) return;
  window.speechSynthesis.cancel();
  var de=_snValuesDe();
  var en=_snValuesEn();
  var nm=_snPlayer();
  var hero=(_selectedChar==='kiz'?'Verse':'Edu');
  var msgs=en?[
    nm+'! This is your special moment!',
    hero+' grew with you. It would not be the same without you!',
    'I am glad you are here, '+nm+'. Happy day!'
  ]:(de?[
    nm+'! Heute ist dein besonderer Moment!',
    hero+' ist mit dir gewachsen. Ohne dich waere es nicht dasselbe!',
    'Gut, dass es dich gibt, '+nm+'. Alles Gute!'
  ]:[
    playerName+'! Bugün senin özel günün!',
    hero+' seninle büyüdü. Sen olmadan olmaz!',
    'İyi ki varsın '+playerName+'. Mutlu yıllar!'
  ]);
  var idx2=0;
  function speakNext(){
    if(idx2>=msgs.length) return;
    var u=new SpeechSynthesisUtterance(msgs[idx2++]);
    u.lang=en?'en-US':(de?'de-DE':'tr-TR');u.rate=0.88;u.pitch=1.1;u.volume=1;
    u.onend=function(){setTimeout(speakNext,400);};
    window.speechSynthesis.speak(u);
  }
  setTimeout(speakNext, 800);
}

function _snPlayAudio(){
  var a=document.getElementById('sn-audio');
  if(a){ a.currentTime=0; a.play().catch(function(){}); }
}
var _ADA_TRACKS=[
  {name:'Cairo Arabian', src:'data:audio/mp3;base64,'},
  {name:'Golden Sand Oud', src:'data:audio/mp3;base64,'},
  {name:'Posh Oud', src:'data:audio/mp3;base64,'},
  {name:'Oriental Song', src:'data:audio/mp3;base64,'},
  {name:'İslami Müzik',  src:'data:audio/mpeg;base64,'},
  {name:'Kuş Sesleri',   src:'data:audio/mpeg;base64,'},
  {name:'Neşeli Çocuk',  src:'data:audio/mpeg;base64,'},
  {name:'Çocuk Müziği',  src:'data:audio/mpeg;base64,'},
];
var _adaAudio=null,_adaIdx=0;

function _adaPlay(i){
  if(_adaAudio){_adaAudio.pause();_adaAudio.remove();_adaAudio=null;}
  _adaIdx=i;
  _adaAudio=document.createElement('audio');
  _adaAudio.src=_ADA_TRACKS[i].src;
  _adaAudio.loop=true;_adaAudio.volume=0.6;
  document.body.appendChild(_adaAudio);
  _adaAudio.play().catch(function(){});
  // Aktif parça highlight
  if(typeof _adaMarkActive==='function') _adaMarkActive(i);
  // İsim güncelle
  var names=(evValuesOn()&&evValuesLang()==='en')?['Cairo Melody','Golden Sand Oud','Elegant Oud','Eastern Melody','Peaceful Background','Birdsong','Happy Children',"Children's Music"]:['Kahire Ezgisi','Altin Kum Ud','Zarif Ud','Dogu Ezgisi','Huzurlu Fon','Kus Sesleri','Neseli Cocuklar','Cocuk Muzigi'];
  var nm=document.getElementById('ada-track-name');
  if(nm) nm.textContent=String.fromCodePoint(0x1F3B5)+' '+(names[i]||'Music');
  var pb=document.getElementById('adaPlayBtn');
  if(pb) pb.textContent=String.fromCharCode(10073)+String.fromCharCode(10073);
  // Baloncuk ikonu çalan nota olsun
  var bb=document.getElementById('ada-bubble');
  if(bb) bb.textContent=String.fromCharCode(10073)+String.fromCharCode(10073);
}
function _adaToggle(){
  if(!_adaAudio){_adaPlay(_adaIdx);return;}
  var bb=document.getElementById('ada-bubble');
  if(_adaAudio.paused){
    _adaAudio.play();
    var pb=document.getElementById('adaPlayBtn'); if(pb) pb.textContent=String.fromCharCode(10073)+String.fromCharCode(10073);
    if(bb) bb.textContent=String.fromCharCode(10073)+String.fromCharCode(10073);
  } else {
    _adaAudio.pause();
    var pb2=document.getElementById('adaPlayBtn'); if(pb2) pb2.textContent=String.fromCharCode(9654);
    if(bb) bb.textContent=String.fromCodePoint(0x1F3B5);
  }
}
function _adaStop(){
  if(_adaAudio){_adaAudio.pause();_adaAudio.remove();_adaAudio=null;}
  var m=document.getElementById('ada-muzik');if(m)m.style.display='none';
  // paneli kapat
  var l=document.getElementById('ada-layers');
  if(l){l.style.pointerEvents='none';l.style.opacity='0';l.style.transform='translateY(8px) scale(.95)';}
  var bb=document.getElementById('ada-bubble');if(bb)bb.textContent='🎵';
}


/* EDUVERSE_VALUES_DEEP_GERMAN_CLEANUP */
(function(){
  function deOn(){ try{return evValuesOn()&&evValuesLang()==='de';}catch(e){return false;} }
  function cleanText(t){
    if(!deOn() || !t) return t;
    var x=String(t);
    var exact={
      'Giy':'Anziehen','Cikar':'Ausziehen','Giyili':'Wird getragen','Henuz yok':'Noch nichts',
      'Tumu':'Alle','Baslik':'Kopf','Kiyafet':'Kleidung','Aksesuar':'Accessoires','Sirt':'Ruecken','Kostum':'Kostuem',
      'Ebeveyn Takip Raporu':'Elternbericht','Lernbericht':'Lernbericht','Bericht':'Bericht','Rapor':'Bericht',
      'Bugun':'Heute','hak kaldi':'Versuche uebrig','parca':'Teile','Tamam':'Fertig','Puzzle Odasi':'Puzzlewelt','Sinema Odasi':'Filmstudio'
    };
    if(exact[x]) return exact[x];
    var pairs=[
      [/giydim/ig,'angezogen'],[/giyin/ig,'anziehen'],[/giy/ig,'anziehen'],[/cikar/ig,'ausziehen'],[/giyili/ig,'wird getragen'],
      [/Dukkan|dukkan|dukkani/ig,'Shop'],[/Laden Raum|Laden-Raum/ig,'Shop'],[/Puzzle Raum|Puzzle-Raum/ig,'Puzzlewelt'],[/Kino Raum|Kino-Raum/ig,'Filmstudio'],
      [/ilerleme\s*beructu|ilerleme\s*bericht|ilerleme\s*raporu/ig,'Lernbericht'],[/ebeveyn\s*beructu|ebeveyn\s*bericht|ebeveyn\s*takip\s*raporu/ig,'Elternbericht'],[/beructu/ig,'Bericht']
    ];
    pairs.forEach(function(p){ x=x.replace(p[0],p[1]); });
    if(window.eduverseGermanClean) x=window.eduverseGermanClean(x);
    return x;
  }
  window.eduverseDeepGermanText=cleanText;
  window.evPuzzleCatName=function(cat){
    if(!cat) return '';
    if(window.eduverseValuesOn&&window.eduverseValuesOn()&&window.eduverseValuesLang&&window.eduverseValuesLang()==='en'){
      return {kabe:'Kaaba',cami:'Mosque',turkiye:'Turkey',fil:'Elephant',aslan:'Lion',uzay:'Space',kuran:'Quran',agac:'Tree',aile:'Family Home',kelebek:'Butterfly',deniz:'Underwater',beyin:'Brain'}[cat.id]||cat.name;
    }
    if(window.eduverseValuesOn&&window.eduverseValuesOn()&&window.eduverseValuesLang&&window.eduverseValuesLang()==='fr'){
      return {kabe:'Maison des valeurs',cami:'Maison du savoir',turkiye:'Carte du monde',fil:'Elephant',aslan:'Lion',uzay:'Espace',kuran:'Livre',agac:'Arbre',aile:'Maison familiale',kelebek:'Papillon',deniz:'Sous-marin',beyin:'Cerveau'}[cat.id]||cat.name;
    }
    if(window.eduverseValuesOn&&window.eduverseValuesOn()&&window.eduverseValuesLang&&window.eduverseValuesLang()==='ar'){
      return {kabe:'\u0628\u064a\u062a \u0627\u0644\u0642\u064a\u0645',cami:'\u0628\u064a\u062a \u0627\u0644\u0645\u0639\u0631\u0641\u0629',turkiye:'\u062e\u0631\u064a\u0637\u0629 \u0627\u0644\u0639\u0627\u0644\u0645',fil:'\u0641\u064a\u0644',aslan:'\u0623\u0633\u062f',uzay:'\u0627\u0644\u0641\u0636\u0627\u0621',kuran:'\u0643\u062a\u0627\u0628',agac:'\u0634\u062c\u0631\u0629',aile:'\u0628\u064a\u062a \u0627\u0644\u0639\u0627\u0626\u0644\u0629',kelebek:'\u0641\u0631\u0627\u0634\u0629',deniz:'\u062a\u062d\u062a \u0627\u0644\u0645\u0627\u0621',beyin:'\u062f\u0645\u0627\u063a'}[cat.id]||cat.name;
    }
    if(!deOn()) return cat.name;
    return {kabe:'Wertehaus',cami:'Lernhaus',turkiye:'Weltkarte',fil:'Elefant',aslan:'Loewe',uzay:'Weltall',kuran:'Buch',agac:'Baum',aile:'Familienhaus',kelebek:'Schmetterling',deniz:'Unterwasser',beyin:'Gehirn'}[cat.id]||cleanText(cat.name);
  };
  var oldReport=window.buildReportHTML||buildReportHTML;
  if(oldReport && !oldReport._deWrapped){
    var wrapped=function(data){
      var html=oldReport.apply(this,arguments);
      if(!deOn()) return html;
      var rep={
        'Dua Evi':'EduVerse Werte','* Lernbericht *':'* Lernbericht *','* Ebeveyn Takip Raporu *':'* Elternbericht *',
        'BUGUNKU DURUM':'HEUTIGER STAND','PUAN':'PUNKTE','Maksimum seviye!':'Maximales Level!','puan':'Punkte',
        'Bugun henuz bir oda ziyaret edilmedi.':'Heute wurde noch kein Raum besucht.','Henuz veri yok':'Noch keine Daten'
      };
      Object.keys(rep).forEach(function(k){ html=html.split(k).join(rep[k]); });
      html=html.replace(/Ebeveyn Takip Raporu/g,'Elternbericht');
      html=html.replace(/Bebek Okisi/g,'Baby Oki').replace(/Kucuk Okisi/g,'Kleiner Oki').replace(/Okul Okisi/g,'Schul-Oki').replace(/Kahraman Okisi/g,'Helden-Oki').replace(/Yildiz Okisi/g,'Stern-Oki').replace(/Melek Okisi/g,'Sternen-Oki');
      return html;
    };
    wrapped._deWrapped=true;
    buildReportHTML=wrapped; window.buildReportHTML=wrapped;
  }
})();



(function(){
  function deOn(){ try{return evValuesOn&&evValuesOn()&&evValuesLang&&evValuesLang()==='de';}catch(e){return false;} }
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function n(v){v=parseInt(v||0,10);return isNaN(v)?0:v;}
  function roomName(id){return {ders:'Lernen',atlas:'Welt-Entdecker',puzzle:'Puzzle',nefes:'Atem-Raum',sanat:'Kreativraum',boyama:'Malraum',refleks:'Reflex-Raum',hayvanat:'Tierwelt',kelime:'Woerter',gorev:'Aufgaben',odak:'Fokus-Raum',lazer:'Laser-Raum',sinema:'Kino',okul:'Schulraum',dukkan:'Laden',market:'Laden',muzik:'Musik',oyuncak:'Spiel',ada:'Insel',caliskan:'Lernziel',cevre:'Natur',aile:'Familie'}[id]||'Lernraum';}
  function cleanGermanParentReport(data){
    data=data||{};
    var today=new Date().toLocaleDateString('de-DE',{weekday:'long',year:'numeric',month:'long',day:'numeric'});
    var visited=[]; try{var rv=JSON.parse(localStorage.getItem('dei_visited')||'{}'); visited=rv[new Date().toDateString()]||data.roomsVisited||[];}catch(e){visited=data.roomsVisited||[];}
    var used=[]; (visited||[]).forEach(function(id){if(id&&used.indexOf(id)<0) used.push(id);});
    var roomHtml=used.slice(0,6).map(function(id){return '<div style="background:#fff;border:1px solid #dfe7f5;border-radius:12px;padding:12px 14px;margin-bottom:8px;"><b style="color:#173d6b;">'+esc(roomName(id))+'</b><div style="font-size:.78rem;line-height:1.55;color:#42536d;margin-top:4px;">Heute wurde spielerisch gelernt. Fragen Sie nach dem Lieblingsmoment und loben Sie Neugier, Ruhe und Ausdauer.</div></div>';}).join('');
    if(!roomHtml) roomHtml='<div style="padding:14px;border:1px dashed #ccd6e8;border-radius:12px;color:#66758d;font-size:.82rem;">Heute wurden noch keine Raumdaten gespeichert.</div>';
    var bars=(data.weekData||[]).map(function(d){var w=n(d.words);var h=Math.max(8,Math.min(54,w*8));return '<div style="flex:1;text-align:center;"><div style="height:60px;display:flex;align-items:flex-end;justify-content:center;"><div style="width:70%;height:'+h+'px;background:'+(d.isToday?'#f4b740':'#7aa7e8')+';border-radius:7px 7px 0 0;"></div></div><div style="font-size:.62rem;color:#607086;font-weight:800;margin-top:4px;">'+w+'</div></div>';}).join('');
    return '<div style="font-family:Nunito,Arial,sans-serif;background:#f6f8fc;color:#172033;margin:0;">'
      +'<div style="background:linear-gradient(135deg,#10294f,#286b7a);color:#fff;padding:22px 24px;"><div style="font-size:1.55rem;font-weight:900;color:#ffe08a;">EduVerse Werte</div><div style="font-size:.86rem;font-weight:800;opacity:.84;margin-top:4px;">Elternbericht</div><div style="display:flex;justify-content:space-between;gap:12px;margin-top:14px;font-size:.76rem;opacity:.92;"><span>'+esc(today)+'</span><span>'+esc(data.name||playerName||'EduVerse Kind')+'</span></div></div>'
      +'<div style="padding:16px 18px;"><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:14px;">'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:12px;padding:12px 8px;text-align:center;"><div style="font-size:.66rem;color:#6f7f95;font-weight:900;">PUNKTE</div><div style="font-size:1.2rem;color:#173d6b;font-weight:900;">'+n(data.totalScore)+'</div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:12px;padding:12px 8px;text-align:center;"><div style="font-size:.66rem;color:#6f7f95;font-weight:900;">SERIE</div><div style="font-size:1.2rem;color:#173d6b;font-weight:900;">'+n(data.streak)+'</div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:12px;padding:12px 8px;text-align:center;"><div style="font-size:.66rem;color:#6f7f95;font-weight:900;">WOERTER</div><div style="font-size:1.2rem;color:#173d6b;font-weight:900;">'+n(data.totalWords)+'</div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:12px;padding:12px 8px;text-align:center;"><div style="font-size:.66rem;color:#6f7f95;font-weight:900;">RAEUME</div><div style="font-size:1.2rem;color:#173d6b;font-weight:900;">'+n(data.rooms)+'</div></div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:14px;padding:14px;margin-bottom:14px;"><b style="color:#173d6b;">Lernstand</b><div style="font-size:.82rem;color:#40516d;line-height:1.55;margin-top:6px;">Dieser Values-Bericht ist neutral, international und ohne religioese Inhalte. Er zeigt Lernfreude, Neugier und regelmaessige Aktivitaet.</div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:14px;padding:14px;margin-bottom:14px;"><b style="color:#173d6b;">Letzte 7 Tage</b><div style="display:flex;align-items:flex-end;gap:5px;margin-top:10px;">'+bars+'</div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:14px;padding:14px;margin-bottom:14px;"><b style="color:#173d6b;">Staerkenprofil</b><div style="margin-top:8px;"><span style="display:inline-block;background:#edf5ff;color:#17446f;border-radius:999px;padding:6px 10px;font-size:.75rem;font-weight:900;margin:3px;">Neugier</span><span style="display:inline-block;background:#edf5ff;color:#17446f;border-radius:999px;padding:6px 10px;font-size:.75rem;font-weight:900;margin:3px;">Ausdauer</span><span style="display:inline-block;background:#edf5ff;color:#17446f;border-radius:999px;padding:6px 10px;font-size:.75rem;font-weight:900;margin:3px;">Fokus</span></div></div>'
      +'<div style="background:#fff;border:1px solid #e1e8f3;border-radius:14px;padding:14px;margin-bottom:14px;"><b style="color:#173d6b;">Besuchte Bereiche</b><div style="margin-top:10px;">'+roomHtml+'</div></div>'
      +'<div style="background:#eaf4ef;border:1px solid #cfe7dc;border-radius:14px;padding:14px;color:#2b5b46;font-size:.82rem;line-height:1.55;"><b>Elternimpuls:</b> Stellen Sie eine kurze positive Frage: Was war heute dein Lieblingsmoment?</div></div></div>';
  }
  var oldBuild=window.buildReportHTML||buildReportHTML;
  window.eduverseCleanGermanParentReport=cleanGermanParentReport;
  buildReportHTML=function(data){ if(deOn()) return cleanGermanParentReport(data); return oldBuild.apply(this,arguments); };
  window.buildReportHTML=buildReportHTML;
})();





